import { useEffect, useState, useCallback } from 'react';
import { 
  Package, 
  Plus, 
  Filter, 
  Download, 
  Search,
  AlertTriangle,
  Eye,
  Edit,
  Trash2,
} from 'lucide-react';
import { useUIStore, useNotificationStore } from '../../store';
import { inventoryApi } from '../../api';
import DataTable from '../../components/ui/DataTable';
import StatusBadge from '../../components/ui/StatusBadge';
import Button from '../../components/ui/Button';
import Modal from '../../components/ui/Modal';
import Drawer from '../../components/ui/Drawer';
import { SkeletonCard } from '../../components/common/Skeleton';

const Inventory = () => {
  const { setPageTitle, setBreadcrumbs } = useUIStore();
  const { success, error: showError } = useNotificationStore();

  const [loading, setLoading] = useState(true);
  const [items, setItems] = useState([]);
  const [stats, setStats] = useState(null);
  const [pagination, setPagination] = useState({ page: 1, limit: 10, total: 0 });
  const [filters, setFilters] = useState({ search: '', category: '', status: '' });
  const [selectedItem, setSelectedItem] = useState(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);

  useEffect(() => {
    setPageTitle('Inventory Management');
    setBreadcrumbs(['Home', 'Inventory']);
  }, []);

  useEffect(() => {
    fetchInventory();
    fetchStats();
  }, [pagination.page, filters]);

  const fetchInventory = async () => {
    try {
      setLoading(true);
      const response = await inventoryApi.getAll({
        page: pagination.page,
        limit: pagination.limit,
        ...filters,
      });
      if (response.success) {
        setItems(response.data.items || []);
        setPagination(prev => ({ ...prev, total: response.data.total || 0 }));
      }
    } catch (err) {
      showError(err.message || 'Failed to load inventory');
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const response = await inventoryApi.getStats();
      if (response.success) {
        setStats(response.data);
      }
    } catch (err) {
      // Stats are secondary, don't show error
    }
  };

  const handleDelete = async () => {
    if (!itemToDelete) return;
    try {
      await inventoryApi.delete(itemToDelete.id);
      success('Item deleted successfully');
      setDeleteModalOpen(false);
      setItemToDelete(null);
      fetchInventory();
    } catch (err) {
      showError(err.message || 'Failed to delete item');
    }
  };

  const handleViewDetails = (item) => {
    setSelectedItem(item);
    setDrawerOpen(true);
  };

  const columns = [
    { 
      key: 'sku', 
      label: 'SKU', 
      width: '120px',
      render: (value) => (
        <span style={{ fontFamily: 'monospace', color: 'var(--accent-primary)' }}>{value}</span>
      )
    },
    { key: 'name', label: 'Product Name' },
    { key: 'category', label: 'Category' },
    { 
      key: 'quantity', 
      label: 'Quantity', 
      align: 'right',
      render: (value, row) => (
        <span style={{ 
          color: row.lowStock ? 'var(--accent-warning)' : 'var(--text-primary)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'flex-end',
          gap: 'var(--spacing-xs)',
        }}>
          {row.lowStock && <AlertTriangle size={14} />}
          {value?.toLocaleString()}
        </span>
      )
    },
    { key: 'facility', label: 'Facility' },
    { 
      key: 'status', 
      label: 'Status',
      render: (value) => <StatusBadge status={value} size="sm" />
    },
    { 
      key: 'expiryDate', 
      label: 'Expiry',
      render: (value) => value ? new Date(value).toLocaleDateString() : '-'
    },
    {
      key: 'actions',
      label: '',
      width: '100px',
      render: (_, row) => (
        <div style={{ display: 'flex', gap: 'var(--spacing-xs)' }}>
          <button
            onClick={() => handleViewDetails(row)}
            style={{
              padding: 'var(--spacing-xs)',
              backgroundColor: 'transparent',
              border: 'none',
              color: 'var(--text-muted)',
              cursor: 'pointer',
              borderRadius: 'var(--radius-sm)',
            }}
          >
            <Eye size={16} />
          </button>
          <button
            onClick={() => { setItemToDelete(row); setDeleteModalOpen(true); }}
            style={{
              padding: 'var(--spacing-xs)',
              backgroundColor: 'transparent',
              border: 'none',
              color: 'var(--accent-danger)',
              cursor: 'pointer',
              borderRadius: 'var(--radius-sm)',
            }}
          >
            <Trash2 size={16} />
          </button>
        </div>
      )
    },
  ];

  const statCards = [
    { label: 'Total Items', value: stats?.totalItems?.toLocaleString() || '-', color: 'var(--accent-primary)' },
    { label: 'Low Stock', value: stats?.lowStock || '-', color: 'var(--accent-warning)' },
    { label: 'Expired', value: stats?.expired || '-', color: 'var(--accent-danger)' },
    { label: 'Categories', value: stats?.categories || '-', color: 'var(--accent-info)' },
  ];

  return (
    <div className="animate-fadeIn">
      {/* Header */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: 'var(--spacing-lg)',
        }}
      >
        <div>
          <h1
            style={{
              fontSize: 'var(--font-size-2xl)',
              fontWeight: 700,
              color: 'var(--text-primary)',
              marginBottom: 'var(--spacing-xs)',
            }}
          >
            Inventory Management
          </h1>
          <p style={{ fontSize: 'var(--font-size-sm)', color: 'var(--text-muted)' }}>
            Track and manage pharmaceutical inventory across all facilities
          </p>
        </div>
        <div style={{ display: 'flex', gap: 'var(--spacing-sm)' }}>
          <Button variant="secondary" leftIcon={Download}>
            Export
          </Button>
          <Button variant="primary" leftIcon={Plus}>
            Add Item
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(4, 1fr)',
          gap: 'var(--spacing-md)',
          marginBottom: 'var(--spacing-lg)',
        }}
      >
        {loading ? (
          Array.from({ length: 4 }).map((_, i) => <SkeletonCard key={i} />)
        ) : (
          statCards.map((stat, index) => (
            <div
              key={index}
              style={{
                padding: 'var(--spacing-lg)',
                backgroundColor: 'var(--bg-card)',
                borderRadius: 'var(--radius-lg)',
                border: '1px solid var(--border-primary)',
              }}
            >
              <div style={{ fontSize: 'var(--font-size-sm)', color: 'var(--text-muted)', marginBottom: 'var(--spacing-xs)' }}>
                {stat.label}
              </div>
              <div style={{ fontSize: 'var(--font-size-2xl)', fontWeight: 700, color: stat.color }}>
                {stat.value}
              </div>
            </div>
          ))
        )}
      </div>

      {/* Filters */}
      <div
        style={{
          display: 'flex',
          gap: 'var(--spacing-md)',
          marginBottom: 'var(--spacing-md)',
          padding: 'var(--spacing-md)',
          backgroundColor: 'var(--bg-card)',
          borderRadius: 'var(--radius-lg)',
          border: '1px solid var(--border-primary)',
        }}
      >
        <div style={{ position: 'relative', flex: 1, maxWidth: '320px' }}>
          <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-muted)' }} />
          <input
            type="text"
            placeholder="Search inventory..."
            value={filters.search}
            onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
            style={{
              width: '100%',
              padding: 'var(--spacing-sm) var(--spacing-sm) var(--spacing-sm) 36px',
              backgroundColor: 'var(--bg-secondary)',
              border: '1px solid var(--border-primary)',
              borderRadius: 'var(--radius-md)',
              color: 'var(--text-primary)',
              fontSize: 'var(--font-size-sm)',
            }}
          />
        </div>
        <select
          value={filters.category}
          onChange={(e) => setFilters(prev => ({ ...prev, category: e.target.value }))}
          style={{
            padding: 'var(--spacing-sm) var(--spacing-md)',
            backgroundColor: 'var(--bg-secondary)',
            border: '1px solid var(--border-primary)',
            borderRadius: 'var(--radius-md)',
            color: 'var(--text-primary)',
            fontSize: 'var(--font-size-sm)',
          }}
        >
          <option value="">All Categories</option>
          <option value="vaccines">Vaccines</option>
          <option value="antibiotics">Antibiotics</option>
          <option value="analgesics">Analgesics</option>
          <option value="supplies">Medical Supplies</option>
        </select>
        <select
          value={filters.status}
          onChange={(e) => setFilters(prev => ({ ...prev, status: e.target.value }))}
          style={{
            padding: 'var(--spacing-sm) var(--spacing-md)',
            backgroundColor: 'var(--bg-secondary)',
            border: '1px solid var(--border-primary)',
            borderRadius: 'var(--radius-md)',
            color: 'var(--text-primary)',
            fontSize: 'var(--font-size-sm)',
          }}
        >
          <option value="">All Status</option>
          <option value="available">Available</option>
          <option value="low_stock">Low Stock</option>
          <option value="out_of_stock">Out of Stock</option>
          <option value="expired">Expired</option>
        </select>
      </div>

      {/* Data Table */}
      <div
        style={{
          backgroundColor: 'var(--bg-card)',
          borderRadius: 'var(--radius-lg)',
          border: '1px solid var(--border-primary)',
          overflow: 'hidden',
        }}
      >
        <DataTable
          columns={columns}
          data={items}
          loading={loading}
          pagination={{
            page: pagination.page,
            limit: pagination.limit,
            total: pagination.total,
            onChange: (page) => setPagination(prev => ({ ...prev, page })),
          }}
          emptyMessage="No inventory items found"
        />
      </div>

      {/* Details Drawer */}
      <Drawer
        isOpen={drawerOpen}
        onClose={() => { setDrawerOpen(false); setSelectedItem(null); }}
        title="Item Details"
        size="md"
      >
        {selectedItem && (
          <div style={{ padding: 'var(--spacing-md)' }}>
            <div style={{ marginBottom: 'var(--spacing-lg)' }}>
              <label style={{ fontSize: 'var(--font-size-xs)', color: 'var(--text-muted)', textTransform: 'uppercase' }}>SKU</label>
              <div style={{ fontSize: 'var(--font-size-lg)', fontWeight: 600, color: 'var(--text-primary)' }}>{selectedItem.sku}</div>
            </div>
            <div style={{ marginBottom: 'var(--spacing-lg)' }}>
              <label style={{ fontSize: 'var(--font-size-xs)', color: 'var(--text-muted)', textTransform: 'uppercase' }}>Product Name</label>
              <div style={{ fontSize: 'var(--font-size-base)', color: 'var(--text-primary)' }}>{selectedItem.name}</div>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--spacing-md)' }}>
              <div>
                <label style={{ fontSize: 'var(--font-size-xs)', color: 'var(--text-muted)', textTransform: 'uppercase' }}>Category</label>
                <div style={{ fontSize: 'var(--font-size-sm)', color: 'var(--text-primary)' }}>{selectedItem.category}</div>
              </div>
              <div>
                <label style={{ fontSize: 'var(--font-size-xs)', color: 'var(--text-muted)', textTransform: 'uppercase' }}>Quantity</label>
                <div style={{ fontSize: 'var(--font-size-sm)', color: 'var(--text-primary)' }}>{selectedItem.quantity?.toLocaleString()}</div>
              </div>
              <div>
                <label style={{ fontSize: 'var(--font-size-xs)', color: 'var(--text-muted)', textTransform: 'uppercase' }}>Facility</label>
                <div style={{ fontSize: 'var(--font-size-sm)', color: 'var(--text-primary)' }}>{selectedItem.facility}</div>
              </div>
              <div>
                <label style={{ fontSize: 'var(--font-size-xs)', color: 'var(--text-muted)', textTransform: 'uppercase' }}>Status</label>
                <div style={{ marginTop: 'var(--spacing-xs)' }}><StatusBadge status={selectedItem.status} /></div>
              </div>
            </div>
          </div>
        )}
      </Drawer>

      {/* Delete Confirmation Modal */}
      <Modal
        isOpen={deleteModalOpen}
        onClose={() => { setDeleteModalOpen(false); setItemToDelete(null); }}
        title="Confirm Deletion"
        size="sm"
      >
        <p style={{ color: 'var(--text-secondary)', marginBottom: 'var(--spacing-lg)' }}>
          Are you sure you want to delete <strong>{itemToDelete?.name}</strong>? This action cannot be undone.
        </p>
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 'var(--spacing-sm)' }}>
          <Button variant="secondary" onClick={() => { setDeleteModalOpen(false); setItemToDelete(null); }}>
            Cancel
          </Button>
          <Button variant="danger" onClick={handleDelete}>
            Delete
          </Button>
        </div>
      </Modal>
    </div>
  );
};

export default Inventory;
